js="\nlet hunterData=null,hunterBusy=false,hunterPoll=0,hunterCommandBusy=false;\nconst hunterKnownBTC=h=>['stratum.bitaxe.de','stratum.ckpool.org'].includes(String(h||'').toLowerCase());\nconst hunterFmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:d}):'—';\nfunction hunterRender(){const d=hunterData;const $h=id=>document.getElementById(id);const put=(id,t)=>{$h(id).textContent=t};if(!d){for(const id of ['odday','odmonth','odyear','odevery'])put(id,'—');put('hunterstatus','Нет связи с BTC Hunter. Штатный майнинг не зависит от этого блока.');for(const id of ['hunterstats','hunterodds','huntercandidate','hunterpools','hunterresults'])put(id,'—');put('hunterrecommend','Данные недоступны');put('huntertrial','Нет связи с контроллером');$h('hunterstart').disabled=true;$h('hunterstop').disabled=true;return;}\nconst secs=Math.max(0,+d.seconds||0),ps=Array.isArray(d.pools)?d.pools:[],stats=S.pools||[];const sum=(k)=>ps.reduce((a,r)=>a+(Number.isFinite(r[k])?r[k]:0),0),a=sum('accepted'),r=sum('rejected'),h=secs>0?sum('work')*4294967296/secs/1e12:0,ready=secs>=300&&a>=100;\nput('hunterstatus','Автономный учёт · '+hunterFmt(secs/60,0)+' мин с запуска');$h('hunterstats').innerHTML=`<div>Полезная работа</div><div>${ready?hunterFmt(h)+' TH/s':'Накопление'}</div><div>Принято / отклонено (V1)</div><div>${a} / ${r}</div><div>Без ответа / ошибка отправки</div><div>${sum('missing')} / ${sum('failed')}</div><div>Доля отклонённых</div><div>${a+r?hunterFmt(100*r/(a+r),3)+'%':'—'}</div>`;\nconst D=+S.pool?.networkDiff;const btcH=secs>0?sum('btcWork')*4294967296/secs/1e12:0;const allKnown=stats.filter(p=>p.enabled).every(p=>hunterKnownBTC(p.host)&&p.proto<=1);if(ready&&sum('btcAccepted')>=100&&allKnown&&hunterKnownBTC(S.pool?.host)&&D>0&&Number.isFinite(D)&&btcH>0){const odds=sec=>hunterFmt(100*-Math.expm1(-btcH*1e12*sec/(4294967296*D)),9)+'%';put('odday',odds(86400));put('odmonth',odds(2592000));put('odyear',odds(31536000));put('odevery',hunterFmt(4294967296*D/(btcH*1e12*31536000),0)+' лет (среднее)');put('hunterodds','Шанс BTC: сутки '+odds(86400)+' · 30 дней '+odds(2592000)+' · год '+odds(31536000)+'. При неизменных сложности и среднем темпе; не гарантия.')}else{for(const id of ['odday','odmonth','odyear','odevery'])put(id,'—');put('hunterodds','Вероятность: ожидаем достаточную выборку и подтверждённую сеть BTC.');}\nconst c=d.candidate||{},states=['Нет кандидатов','Обнаружен','Отправлен','Принят пулом, сеть не подтверждена','Отклонён пулом','Не отправлен / ошибка транспорта','Ответ не получен','Отправлен SV2, индивидуальный ответ неизвестен'];put('huntercandidate','Кандидат: '+(states[c.state]||'Неизвестно')+(c.state?' · пул '+(c.pool+1)+' · '+(c.hash||'')+(c.persisted?'':' · архив не записан'):''));$h('huntercandidate').style.overflowWrap='anywhere';\nconst el=$h('hunterpools');el.textContent='';for(let i=0;i<ps.length;i++){const p=stats[i],m=ps[i];if(!p?.enabled)continue;const item=document.createElement('div');item.style.cssText='padding:10px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere';const b=document.createElement('b');b.textContent=p.host||'Пул '+(i+1);item.append(b,document.createElement('br'));const note=document.createElement('span');note.textContent=(p.lagBlocks>=3?'Отставание '+p.lagMs+' мс ('+p.lagBlocks+' блоков)':'Недостаточно данных о блоках')+' · доставка '+(m.cleanN?m.cleanMs+' мс, пик '+m.cleanMax+' мс':'—')+' · V1: '+m.accepted+' / '+m.rejected+' · '+(p.payout===2?'Выплата '+p.payoutPct+'%':'Выплата не подтверждена');item.append(note);el.append(item)}\nconst eligible=stats.map((p,i)=>({p,i,m:ps[i]})).filter(({p,m})=>p.enabled&&p.connected&&p.proto<=1&&hunterKnownBTC(p.host)&&p.payout===2&&!p.payoutBlocked&&p.lagBlocks>=20&&m?.accepted>=100&&m.rejected/(m.accepted+m.rejected)<=.01&&m.missing===0&&m.failed===0).sort((a,b)=>a.p.lagMs-b.p.lagMs);const active=eligible.find(({p})=>p.workPct===100);if(active&&eligible.length>1&&eligible[0].i!==active.i&&eligible[0].p.proto===active.p.proto&&active.p.lagMs-eligible[0].p.lagMs>=500)put('hunterrecommend','Для ручной проверки: '+eligible[0].p.host+' быстрее по наблюдаемым блокам. Сравните комиссию и длительную стабильность.');else put('hunterrecommend','Оставьте текущий порядок: устойчивого преимущества альтернативы не подтверждено.');\nconst t=d.trial||{},steps=[500,350,250];put('huntertrial',t.state===1?'Этап '+(t.stage+1)+'/3 · '+steps[t.stage]+' мс · '+hunterFmt(t.elapsed/60,1)+' из 30 мин':t.state===2?'Тест завершён. Проверьте таблицу; исходный интервал возвращён.':t.state===3?'Тест остановлен: режим изменился, недостаточно шар или отменено. Исходный интервал возвращён.':'Тест не запущен.');$h('hunterresults').innerHTML=steps.map((x,i)=>`<div>${x} мс</div><div>${t.accepted?.[i]>=100?hunterFmt(t.rates[i]/1000)+' TH/s · '+t.accepted[i]+' / '+t.rejected[i]:'—'}</div>`).join('');$h('hunterstart').disabled=hunterCommandBusy||!cfgReady||!d.taskOk||t.state===1;$h('hunterstop').disabled=hunterCommandBusy||t.state!==1;if(t.state===2&&t.accepted?.[0]>=100){const candidates=[1,2].filter(i=>t.accepted[i]>=100&&Number.isFinite(t.ci95Low?.[i])&&Number.isFinite(t.ci95High?.[0])&&t.ci95Low[i]>t.ci95High[0]&&t.rejected[i]/(t.accepted[i]+t.rejected[i])<=t.rejected[0]/(t.accepted[0]+t.rejected[0])+.005).sort((a,b)=>t.rates[b]-t.rates[a]);$h('huntertrial').textContent+=candidates.length?' Кандидат для повторной проверки: '+steps[candidates[0]]+' мс.':' Достоверного преимущества над 500 мс не видно. Один проход: статистическая неопределённость, нужен повтор.';}\n}\nasync function hunterRefresh(force=false){if(hunterBusy||(!force&&Date.now()-hunterPoll<15000))return;hunterBusy=true;hunterPoll=Date.now();try{const d=await readJson('/api/hunter');if(!d.native||!Array.isArray(d.pools))throw Error('bad hunter');hunterData=d;hunterRender()}catch(e){hunterData=null;hunterRender()}finally{hunterBusy=false}}\nasync function hunterCommand(start){if(hunterCommandBusy||!hunterData)return;if(start&&!confirm('Запустить три измерительных этапа? Майнер автоматически вернёт исходный интервал. Частота, напряжение и пулы не меняются.'))return;hunterCommandBusy=true;hunterRender();try{const r=await fetch('/api/hunter',{method:'POST',body:JSON.stringify({start})});if(!r.ok)throw Error(await r.text());toast(start?'Тест запущен':'Тест остановлен');await hunterRefresh(true)}catch(e){toast('Не удалось: '+e.message)}finally{hunterCommandBusy=false;hunterRender()}}\n"
